    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def intersection(interval1, interval2):
    start1, end1 = interval1
    start2, end2 = interval2

    start = max(start1, start2)
    end = min(end1, end2)

    if start > end:
        return "NO"

    length = end - start

    if length <= 1:
        return "NO"

    if is_prime(length):
        return "YES"
    else:
        return "NO"

